mapper.sql:

and tpd.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06}


    and fprod_type.TYPE_6 = #{finprodType}



    and fp.FINPROD_MARKET_ID = #{finprodMarketId}



    and nvl(tpda.PAY_TYPE,wtpda.PAY_TYPE) = #{bonusMode}


    and wtdta.conversion_type = #{conversionType}


    and tpd.TRADE_DATE >= to_date(#{conversionTimeStart},'yyyy-mm-dd')
    and tpd.TRADE_DATE <= to_date(#{conversionTimeEnd},'yyyy-mm-dd')

with tmpTable as (
select distinct B_TRADE_ID,hasFlow from (
SELECT B_TRADE_ID,'01' hasFlow FROM TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N}
UNION all
SELECT B_TRADE_ID,'01' hasFlow FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N})
)

mapper.select:

select * from (select temp_data.*,
tmpTable.hasFlow
from(

    /*流程中*/
    SELECT
    #{PAGE_DATE_STATUS03} statusValid,

    tpd.WORKFLOW_ID workflowId
    from
    WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd

    where
    tpd.PS=#{ps}

    and fprod_type.TYPE_6 = #{FUND_ASSET_TYPE_F01}
    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}





        UNION ALL

    SELECT
    #{PAGE_DATE_STATUS05} statusValid,

    null workflowId
    from
    TRD_FIN_PRODUCT_DEAL_TOTAL  tpd

    where
    tpd.PS=#{ps}
    and fprod_type.TYPE_6 = #{FUND_ASSET_TYPE_F01}
    and tpd.TRADE_STATUS = #{TRADE_STATUS01}
    and tpd.IS_CANCEL = #{YESNO_N}


/*撤销数据*/


        UNION ALL

    SELECT
    #{PAGE_DATE_STATUS06} statusValid,

    null workflowId
    FROM
    TRD_FIN_PRODUCT_DEAL_TOTAL  tpd

    where
    tpd.PS=#{ps}
    and fprod_type.TYPE_6 = #{FUND_ASSET_TYPE_F01}
    and tpd.TRADE_STATUS = #{TRADE_STATUS03}
    and tpd.IS_CANCEL = #{YESNO_N}


) temp_data
left join (
select distinct B_TRADE_ID,hasFlow from (
SELECT B_TRADE_ID,'01' hasFlow FROM TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N}
UNION all
SELECT B_TRADE_ID,'01' hasFlow FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL total where total.B_TRADE_ID is not null
and total.TRADE_STATUS = #{TRADE_STATUS01}
and total.FINPROD_TYPE2 = #{finprodTypeTg}
and total.IS_CANCEL = #{YESNO_N})
) tmpTable on tmpTable.B_TRADE_ID = temp_data.TOTLE_TRADE_ID
order by temp_data.registDate desc)
